final Map<String, Uint8List> _decoded = {};

/// PNG bytes of the flag for an ISO 3166-1 alpha-2 code, or null.
Uint8List? flagPng(String code) {
  final key = code.toUpperCase();
  final cached = _decoded[key];
  if (cached != null) return cached;
  final data = _flags[key];
  if (data == null) return null;
  return _decoded[key] = base64Decode(data);
}

/// Whether a flag image exists for [code].
bool hasFlag(String code) => _flags.containsKey(code.toUpperCase());
